// Cross-check the fingerprint code inside a built page against the Python reference (tools/verify_scope.py).
//
//     node tests/check_crypto.js [dist/<trust>/index.html]
//
// It extracts the exact code the page runs (between "crypto:begin" and "crypto:end"), then checks:
//   1. SHA-256 against Node's OpenSSL implementation (fixed and random inputs)
//   2. the RFC 6962 Merkle Tree Hash test vectors
//   3. every fingerprint, check code and link in tests/vectors.json (generated by the Python reference)
//   4. links encoded by the page decode to the same fingerprint in the Python reference
// Node 18+ only; no packages.
const fs = require('fs'), path = require('path'), crypto = require('crypto'), { execFileSync } = require('child_process');
const root = path.resolve(__dirname, '..');
const page = process.argv[2] || path.join(root, 'dist', fs.readdirSync(path.join(root, 'dist')).find(d => fs.existsSync(path.join(root, 'dist', d, 'index.html'))), 'index.html');
const html = fs.readFileSync(page, 'utf8');
const begin = html.indexOf('// crypto:begin'), end = html.indexOf('// crypto:end');
if (begin < 0 || end < 0) throw new Error('crypto block markers not found in ' + page);
const api = new Function(html.slice(begin, end) + '; return { sha256, mth, hex, fingerprintHex, checkCode, encodePayload, decodePayload, itemLine, leafLines };')();
const vectors = JSON.parse(fs.readFileSync(path.join(root, 'tests', 'vectors.json'), 'utf8'));
let checks = 0;
const eq = (a, b, what) => { if (a !== b) throw new Error(`${what}: page gave ${a}, expected ${b}`); checks++; };
const fromHex = h => Uint8Array.from((h.match(/../g) || []).map(x => parseInt(x, 16)));

(async () => {
  for (const s of ['', 'abc', 'a'.repeat(55), 'a'.repeat(56), 'a'.repeat(64), 'a'.repeat(1000), 'Ré-évaluer ✓'])
    eq(api.hex(api.sha256(new TextEncoder().encode(s))), crypto.createHash('sha256').update(s, 'utf8').digest('hex'), `sha256(${JSON.stringify(s.slice(0, 12))})`);
  for (let i = 0; i < 200; i++) {
    const b = crypto.randomBytes(Math.floor(Math.random() * 300));
    eq(api.hex(api.sha256(new Uint8Array(b))), crypto.createHash('sha256').update(b).digest('hex'), `sha256(random ${b.length} bytes)`);
  }
  for (const v of vectors.rfc6962) eq(api.hex(api.mth(v.leaves_hex.map(fromHex))), v.root, `RFC 6962 tree of ${v.leaves_hex.length}`);
  for (const v of vectors.fingerprints) {
    eq(api.fingerprintHex(v.items), v.root, `fingerprint "${v.name}"`);
    eq(api.checkCode(v.root), v.check_code, `check code "${v.name}"`);
  }
  for (const v of vectors.payloads) {
    const got = await api.decodePayload(v.payload);
    eq(JSON.stringify(got.items), JSON.stringify(v.items), `decode "${v.name}" items`);
    eq(JSON.stringify(got.ctx), JSON.stringify(v.context), `decode "${v.name}" context`);
  }
  // page-encoded links must give the same fingerprint in the independent Python reference
  for (const v of vectors.fingerprints.filter(f => f.items.length)) {
    const payload = await api.encodePayload({ t: 'test', p: '', c: 'cross-check' }, v.items);
    const out = execFileSync('python3', ['-I', path.join(root, 'tools', 'verify_scope.py'), payload], { encoding: 'utf8' });
    eq(out.match(/fingerprint:\s+([0-9a-f]{64})/)[1], v.root, `Python reading of page link "${v.name}"`);
  }
  // the fingerprint playground must run exactly the same code as the builder
  const fpPage = path.join(path.dirname(page), 'fingerprint.html');
  if (fs.existsSync(fpPage)) {
    const other = fs.readFileSync(fpPage, 'utf8');
    eq(other.slice(other.indexOf('// crypto:begin'), other.indexOf('// crypto:end')), html.slice(begin, end), 'fingerprint.html crypto block identical to the builder');
  }
  console.log(`crypto cross-check passed: ${checks} checks against Node crypto, RFC 6962 and the Python reference (${path.relative(root, page)})`);
})().catch(e => { console.error('crypto cross-check FAILED: ' + e.message); process.exit(1); });
